// PaxServiceServer is the server API for PaxService service.
// All implementations must embed UnimplementedPaxServiceServer
// for forward compatibility.
//
// Pax 产品 gRPC；协议与模型见 architecture §4/§7.5。
// 兼容策略（code-standards.md §5.4）：只新增字段与方法，不改编号；删除须 reserved。
//
// 当前产品接口包含配置命令与有界只读查询；产品协议版本由双方实现同步。
// 事件流只有一条 Watch。变更命令返回 OperationAck，最终结果经 Watch；
// 历史、规则等查询返回只读快照，不返回私有内核 profile 或凭据。
type PaxServiceServer interface {
	RecheckCurrentPath(context.Context, *CurrentPathRecheckRequest) (*OperationAck, error)
	QueryLogUpdates(context.Context, *LogUpdateRequest) (*LogUpdatePage, error)
	QueryRoutingRules(context.Context, *emptypb.Empty) (*RoutingRulesSnapshot, error)
	QueryRoutingLibrary(context.Context, *emptypb.Empty) (*RoutingLibrarySnapshot, error)
	QueryGeoRules(context.Context, *GeoRulesQuery) (*GeoRulesPage, error)
	MutateRoutingLibrary(context.Context, *RoutingMutationRequest) (*RoutingLibrarySnapshot, error)
	QueryObjectIcon(context.Context, *ObjectIconRequest) (*ObjectIconResult, error)
	QueryLogs(context.Context, *LogQuery) (*LogPage, error)
	QueryLogObjects(context.Context, *LogQuery) (*LogObjectPage, error)
	GetLogDetail(context.Context, *LogDetailRequest) (*LogDetail, error)
	QueryTraffic(context.Context, *TrafficQuery) (*TrafficPage, error)
	QueryTrafficDetail(context.Context, *TrafficDetailRequest) (*TrafficDetail, error)
	ClearLogs(context.Context, *ClearLogsRequest) (*OperationAck, error)
	// 协议版本握手；不兼容时 UI 提示升级，不做兼容降级。
	// Only App-owned temporary sessions support graceful shutdown; legacy services reject it.
	ShutdownAppSession(context.Context, *emptypb.Empty) (*emptypb.Empty, error)
	Hello(context.Context, *HelloRequest) (*HelloResponse, error)
	// 完整快照：冷启动、重连、窗口重新可见时拉取。
	GetSnapshot(context.Context, *GetSnapshotRequest) (*Snapshot, error)
	// 唯一事件流。重连顺序：退避 → Hello → GetSnapshot → Watch(from_seq = snapshot.snapshot_version)。
	Watch(*WatchRequest, grpc.ServerStreamingServer[WatchEvent]) error
	// 整体替换可见页面集合（protocol.md §4.2 R7）。
	SetViewVisibility(context.Context, *ViewVisibility) (*emptypb.Empty, error)
	PreviewRoutes(context.Context, *PreviewRoutesRequest) (*RoutesPreview, error)
	CancelRoutesPreview(context.Context, *CancelRoutesPreviewRequest) (*emptypb.Empty, error)
	ConfirmImportRoutes(context.Context, *ConfirmImportRoutesRequest) (*OperationAck, error)
	AddRoute(context.Context, *RouteEditRequest) (*OperationAck, error)
	UpdateRoute(context.Context, *RouteEditRequest) (*OperationAck, error)
	DeleteRoute(context.Context, *DeleteRouteRequest) (*OperationAck, error)
	GetRouteEditor(context.Context, *GetRouteEditorRequest) (*RouteEditor, error)
	UpdateRouteTLS(context.Context, *UpdateRouteTLSRequest) (*OperationAck, error)
	ConfirmRouteTLSBatch(context.Context, *ConfirmRouteTLSBatchRequest) (*OperationAck, error)
	SaveChainRoute(context.Context, *SaveChainRouteRequest) (*OperationAck, error)
	QueryRouteHistory(context.Context, *RouteHistoryRequest) (*RouteHistoryResponse, error)
	QueryRouteUsage(context.Context, *RouteHistoryRequest) (*RouteUsageResponse, error)
	NotifyPowerEvent(context.Context, *PowerEventRequest) (*emptypb.Empty, error)
	SetProxyEnabled(context.Context, *SetProxyEnabledRequest) (*OperationAck, error)
	ReconnectProxy(context.Context, *emptypb.Empty) (*OperationAck, error)
	SelectRoute(context.Context, *SelectRouteRequest) (*OperationAck, error)
	ImportRoutes(context.Context, *ImportRoutesRequest) (*ImportResult, error)
	DeleteSubscription(context.Context, *DeleteSubscriptionRequest) (*OperationAck, error)
	RefreshSubscription(context.Context, *RefreshSubscriptionRequest) (*OperationAck, error)
	RestoreSubscriptionRoute(context.Context, *RestoreSubscriptionRouteRequest) (*OperationAck, error)
	CancelOperation(context.Context, *CancelOperationRequest) (*OperationAck, error)
	TestRoute(context.Context, *TestRouteRequest) (*OperationAck, error)
	SaveRouteGroups(context.Context, *SaveRouteGroupsRequest) (*OperationAck, error)
	UpdateSettings(context.Context, *UpdateSettingsRequest) (*OperationAck, error)
	GetNetworkPrivacy(context.Context, *emptypb.Empty) (*NetworkPrivacy, error)
	SaveNetworkPrivacy(context.Context, *NetworkPrivacy) (*NetworkPrivacy, error)
	GetMeasurementPreferences(context.Context, *emptypb.Empty) (*MeasurementPreferences, error)
	SaveMeasurementPreferences(context.Context, *MeasurementPreferences) (*MeasurementPreferences, error)
	EvaluateMeasurementPreferences(context.Context, *TestRouteRequest) (*OperationAck, error)
	GetPhysicalEgress(context.Context, *emptypb.Empty) (*PhysicalEgress, error)
	// On-demand, bounded read-only OS observations; never claims all app traffic is captured.
	GetTrafficPathDiagnostics(context.Context, *emptypb.Empty) (*TrafficPathDiagnostics, error)
	DiagnoseConnection(context.Context, *ConnectionDiagnosticRequest) (*TrafficPathDiagnostics, error)
	DiagnoseNetwork(context.Context, *NetworkDiagnosticRequest) (*NetworkDiagnosticReport, error)
	InspectEnvironment(context.Context, *EnvironmentDiagnosticRequest) (*EnvironmentDiagnosticReport, error)
	QueryCFCandidates(context.Context, *emptypb.Empty) (*CFCandidates, error)
	ValidateCFCandidate(context.Context, *CFValidationRequest) (*CFCandidate, error)
	QueryCFWorkspace(context.Context, *CFWorkspaceRequest) (*CFWorkspace, error)
	RunCFTask(context.Context, *CFTaskRequest) (*OperationAck, error)
	mustEmbedUnimplementedPaxServiceServer()
}

